INSERT INTO wastewater VALUES
('W103-01','CN0083','610配料釜及晶化釜清洗废水','2026-07首次环评公示所述既有',NULL,NULL,NULL,NULL,'提浓塔脱盐→废液罐暂存','资质单位定期处置',NULL,'S103-01','WEB_COMPANY','与较晚验收转载中混料釜无冲洗水、特定晶化釜委外并存；非确认当前实际流量'),
('W103-02','CN0083','生活污水、反渗透浓水、地面冲洗废水及初期雨水','2026-07首次环评公示所述既有',NULL,NULL,NULL,NULL,'收集后送共享站','天辰齐翔污水站',NULL,'S103-01','WEB_COMPANY','RO用途与设备未明，不认定为生产废水RO；含全厂非催化剂装置');
INSERT INTO evidence_notes VALUES
('N103-01','CN0083','S103-01','厂址及拟建装置','一、2-3','淄博临淄金山镇南沣路776号；丙烯氨氧化共线利旧3台搅拌釜、喷雾造粒和焙烧；贵金属/氧化铝基新增浸渍釜、环己烷中间罐，共用262网带窑；钛硅升级新增硅溶胶罐；均不改变原产能。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N103-02','CN0083','S103-01','既有废液范围冲突','一、4（2）（4）','610配料及晶化洗液提浓塔脱盐、废液罐暂存后委外；全厂其余四类水入共享站。冷凝废液、静置废液、废催化剂、滤渣、废包装物危废暂存后委外。与W03S16较晚验收转载的混料釜无冲洗水差异保留，不能推定提浓塔一直运行或所有委外水均经提浓。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N103-03','CN0083','S103-02','技改审批节点','标题及日期','2026-10-15报批前公示，未取得图片内报告链接及正式批复，未判定建设或生产。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N103-04','CN0225','S097-01','原设计与验收实际差异','3.6 表3-7','原环评拟设废水处理车间及物化、水解酸化、生物接触氧化、BAF、RO、MVR路线，验收明确未按原方案建设。实际清洗水沉淀压滤回用、必要时RO；无害化还原液原拟冷却结晶、蒸发和过滤，验收改用RO，浓液作为钒产品原料或副产品。2016同行三效蒸发转述不作为2015验收事实，2025许可变更不证明现行工艺。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N103-05','CN0225','S097-01','历史还原及水平衡','3.3、3.4 图3-5','还原反应温度最高80℃，固体含水40%–50%，自然风干；非RO进水温度。图3-5标注实际水平衡新鲜水36.61m³/d（非计量进站或排放流量），其余箭头归属不清不取数。截图访问受阻。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N103-06','CN0355','S103-03','2025Q4外部实际危废流转','二、3 固体废物','垦利石化披露送山东金惠诚处置：加氢废催化剂32.84t、MTBE废催化剂72.7t、废脱氯剂83.08t。为产废方季度申报转移描述，非接收方过磅或许可处理能力；416.6t FCC另送山东齐力，不计金惠诚；不将垦利石化污水站工艺归给金惠诚。','WEB_COMPANY','WEB_TEXT','2026-11-28');
