INSERT INTO membrane_retrofits VALUES ('RT103-01','R103-01','CN0083','upgrade_notice_existing','610_brine_reduction',1,'降低610高浓废液委外量','条件化：确认洗液分股与提浓塔实际状态→预处理试验→耐盐NF/RO浓缩比较→浓液合规委外；不串入共享站事实图','conditional','盐度/有机物与催化剂残固、浓水去向、接管许可、原有提浓能力待核','S103-01；既有洗液提浓脱盐及委外','不假定当前处理量或膜系统','分股流量、盐种、COD、SS、pH、温度、处置费、现有塔能耗','取样和膜相容性/通量试验，物料衡算，核委外合同和边际节约','既有提浓塔优化；源头分流；保持现状',NULL,NULL,NULL,NULL,NULL,NULL,'数据不足，六维评分未知；成本按同一废液边界对比，不给虚构吨水价','2026-11-28');
